export class TurnScopedCacheScope {
  private readonly caches: ClearableTurnScopedCache[] = [];

  createCache<Key, Value>(): TurnScopedCache<Key, Value> {
    const cache = new TurnScopedCacheHandle<Key, Value>();
    this.caches.push(cache);
    return cache;
  }

  beginTurn(): void {
